-- Decode compact lossless runs once, avoiding the LuaJIT constant-table limit.
for i,encoded in ipairs(M.frames) do
 local runs={}
 for entry in encoded:gmatch('[^;]+') do
  local v={};for value in entry:gmatch('[^,]+') do v[#v+1]=tonumber(value) end
