function M.new() return {} end
function M.step(s,m,now,random)
 if not m or m.resource_hex~='72170a55a1f37ff1' then s.id=nil;s.value=nil;s.reserve=nil;s.until_at=nil;return nil end
 local id=m.unit_ref or m.id or m.resource_hex
 if s.id==id and s.value and s.reserve and m.reserve and m.value>s.value and m.value==m.capacity and m.reserve<s.reserve and m.capacity==2 then
  if (random or math.random)()<.001 then s.start=now;s.until_at=now+M.duration end
 end
 if s.time and now<s.time then s.until_at=nil end
 s.id=id;s.value=m.value;s.reserve=m.reserve;s.time=now
 return s.until_at and now<s.until_at and s.start or nil
end
function M.apply(out,m,scale,opacity,now)
 if M.render_paused then return out end
 if m.resource_hex~='72170a55a1f37ff1' or not m.doom_start then return out end
 local f=out[1];local result={f};local elapsed=math.max(0,now-m.doom_start)%M.duration;local idx=M.sequence[#M.sequence][2]
 for _,entry in ipairs(M.sequence) do if elapsed<entry[1] then idx=entry[2];break end end
 local factor=math.min((f.w-16*scale)/M.width,(f.h-10*scale)/M.height)
 local x=f.x+(f.w-M.width*factor)/2;local y=f.y+(f.h-M.height*factor)/2
 for _,r in ipairs(M.frames[idx]) do result[#result+1]={type='rect',x=x+r[1]*factor,y=y+r[2]*factor,w=r[3]*factor,h=r[4]*factor,c=r[5],a=opacity*(r[6] or 1),doom_face=true} end
 return result
end
return M
